import { Mesh, PlaneGeometry, DoubleSide, Object3D } from "three/webgpu";
import {
  NodeMaterial,
  texture,
  uv,
  float,
  mul,
  add,
  sub,
  vec3,
  cameraPosition,
  positionWorld,
} from "three/tsl";
import { gsap } from "gsap";
import * as primitives from "@/primitives";

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {{imageUrl:string,depthMapUrl:string}} assets
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {Array<any>} behaviors
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>Promise<import('three').Texture>} textureLoader
 * @property {{[key:string]:(obj:Object3D,params:any)=>void}} primitives
 * @property {{emit?:(event:string)=>void, navigate?:(url:string)=>void}} [utils]
 */

/**
 * Creates a textured, displacement‑mapped plane with subtle hover animation
 * and click handling.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
  // -----------------------------------------------------------------------
  // Geometry & Textures
  // -----------------------------------------------------------------------
  const geometry = new PlaneGeometry(1, 1, 64, 64); // size 1 unit, 64×64 segments

  const baseMapPromise = ctx.textureLoader(config.assets.imageUrl);
  const depthMapPromise = ctx.textureLoader(config.assets.depthMapUrl);

  // Resolve synchronously – ctx.textureLoader returns a cached texture instantly
  const baseMap = baseMapPromise?.isTexture ? baseMapPromise : undefined;
  const depthMap = depthMapPromise?.isTexture ? depthMapPromise : undefined;

  // -----------------------------------------------------------------------
  // Node Material with displacement
  // -----------------------------------------------------------------------
  const baseTexNode = texture(baseMap);
  const depthTexNode = texture(depthMap);

  // Subtle displacement scale (0.15 scene units max height)
  const displacementScale = float(0.12);

  const material = new NodeMaterial();
  material.color = baseTexNode; // albedo
  material.displacement = mul(depthTexNode, displacementScale);
  material.side = DoubleSide;
  material.transparent = true;

  // -----------------------------------------------------------------------
  // Mesh & Transform
  // -----------------------------------------------------------------------
  const mesh = new Mesh(geometry, material);
  mesh.position.set(
    config.position?.x ?? 0,
    config.position?.y ?? 0,
    config.position?.z ?? 0
  );
  mesh.rotation.set(
    config.rotation?.x ?? 0,
    config.rotation?.y ?? 0,
    config.rotation?.z ?? 0
  );
  mesh.scale.set(
    config.scale?.x ?? 1,
    config.scale?.y ?? 1,
    config.scale?.z ?? 1
  );

  // -----------------------------------------------------------------------
  // Apply Cinematic Primitives (if any)
  // -----------------------------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === "function") {
        fn(mesh, primitive.params);
      }
    }
  }

  // -----------------------------------------------------------------------
  // Interaction Handlers
  // -----------------------------------------------------------------------
  const handlerStore = {
    hoverIn: null,
    hoverOut: null,
    click: null,
  };

  // Rise‑in animation on hover (subtle 0.15 scene units)
  const riseTimeline = gsap.timeline({ paused: true });
  riseTimeline.to(
    mesh.position,
    {
      y: mesh.position.y + 0.15,
      duration: 0.7,
      ease: "power3.out",
    },
    0
  );

  handlerStore.hoverIn = () => {
    riseTimeline.play();
  };
  handlerStore.hoverOut = () => {
    riseTimeline.reverse();
  };

  // Click handling: emit event and optional navigation
  handlerStore.click = () => {
    if (ctx.utils?.emit) {
      ctx.utils.emit("hub-features.select");
    }
    // Data‑binding placeholder – URL would be fetched elsewhere
    if (ctx.utils?.navigate) {
      // Assuming a pre‑resolved URL is stored somewhere accessible
      // ctx.utils.navigate(checkoutUrl);
    }
  };

  // -----------------------------------------------------------------------
  // Expose handlers via userData
  // -----------------------------------------------------------------------
  mesh.userData.handlers = {
    hover: handlerStore.hoverIn,
    unhover: handlerStore.hoverOut,
    click: handlerStore.click,
  };

  // -----------------------------------------------------------------------
  // Cleanup
  // -----------------------------------------------------------------------
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    baseMap?.dispose?.();
    depthMap?.dispose?.();
    riseTimeline.kill();
    // Release any primitive resources if they expose a cleanup
    // (not required by current spec)
  };

  // -----------------------------------------------------------------------
  // Return the prepared Object3D
  // -----------------------------------------------------------------------
  return mesh;
}
